# packet.StructureBlockUpdate{Position: protocol.BlockPos{1, 2, 3},
#   StructureName: "name", FilteredStructureName: "", DataField: "df",
#   IncludePlayers: true, ShowBoundingBox: false, StructureBlockType: 1,
#   Settings: protocol.StructureSettings{PaletteName: "default", IgnoreEntities: true,
#     IgnoreBlocks: false, AllowNonTickingChunks: true, Size: protocol.BlockPos{1, 2, 3},
#     Offset: protocol.BlockPos{4, 5, 6}, LastEditingPlayerUniqueID: 7, Rotation: 1,
#     Mirror: 1, AnimationMode: 2, AnimationDuration: 0.5, Integrity: 1.0, Seed: 9,
#     Pivot: mgl32.Vec3{0, 1, 2}},
#   RedstoneSaveMode: 1, ShouldTrigger: true, Waterlogged: false}
V1001 = bytes.fromhex(
    "020406046e616d65000264660100020764656661756c74010001020406080a0c0e0101020000003f0000803f09000000000000000000803f00000040020100"
)

# TODO: confirm against BDS: gophertunnel writes FilteredStructureName as a plain string, the r26_u4 dump marks
# RedactableString's Redacted optional, so gophertunnel has to give.
# generated by gophertunnel b8bd735:
# packet.StructureBlockUpdate{Position: protocol.BlockPos{1, 2, 3},
#   StructureName: "name", FilteredStructureName: "", DataField: "df",
#   IncludePlayers: true, ShowBoundingBox: false, StructureBlockType: 1,
#   Settings: protocol.StructureSettings{PaletteName: "default", IgnoreEntities: true,
#     IgnoreBlocks: false, AllowNonTickingChunks: true, Size: protocol.BlockPos{1, 2, 3},
#     Offset: protocol.BlockPos{4, 5, 6}, LastEditingPlayerUniqueID: 7, Rotation: 1,
#     Mirror: 1, AnimationMode: 2, AnimationDuration: 0.5, Integrity: 1.0, Seed: 9,
#     Pivot: mgl32.Vec3{0, 1, 2}},
#   RedstoneSaveMode: 1, ShouldTrigger: true, Waterlogged: false}
V2168 = bytes.fromhex(
    "020406046e616d65000264660100020764656661756c74010001020406080a0c0e0101020000003f0000803f09000000000000000000803f00000040010100"
)

PACKET_1001 = v1001.StructureBlockUpdatePacket(
    block_pos=v1001.BlockPos(x=1, y=2, z=3),
    data=v1001.StructureEditorData(
        structure_name=v1001.RedactableString(unredacted_string="name", redacted_string=""),
        data_field="df",
        include_players=True,
        show_bounding_box=False,
        type=v1001.StructureBlockType.SAVE,
        settings=v1001.StructureSettings(
            palette_name="default",
            ignore_entities=True,
            ignore_blocks=False,
            allow_non_ticking_player_and_ticking_area_chunks=True,
            structure_size=v1001.BlockPos(x=1, y=2, z=3),
            structure_offset=v1001.BlockPos(x=4, y=5, z=6),
            last_touched_by_player=7,
            rotation=v1001.Rotation.ROTATE_90,
            mirror=v1001.Mirror.X,
            animation_mode=v1001.AnimationMode.BLOCKS,
            animation_seconds=0.5,
            integrity_value=1.0,
            integrity_seed=9,
            pivot=v1001.Vec3(x=0.0, y=1.0, z=2.0),
        ),
        redstone_save_mode=v1001.StructureRedstoneSaveMode.SAVES_TO_DISK,
    ),
    trigger=True,
    is_waterlogged=False,
)

PACKET_2168 = v2168.StructureBlockUpdatePacket(
    block_pos=v2168.BlockPos(x=1, y=2, z=3),
    data=v2168.StructureEditorData(
        structure_name=v2168.RedactableString(unredacted_string="name", redacted_string=None),
        data_field="df",
        include_players=True,
        show_bounding_box=False,
        type=v2168.StructureBlockType.SAVE,
        settings=v2168.StructureSettings(
            palette_name="default",
            ignore_entities=True,
            ignore_blocks=False,
            allow_non_ticking_player_and_ticking_area_chunks=True,
            structure_size=v2168.BlockPos(x=1, y=2, z=3),
            structure_offset=v2168.BlockPos(x=4, y=5, z=6),
            last_touched_by_player=7,
            rotation=v2168.Rotation.ROTATE_90,
            mirror=v2168.Mirror.X,
            animation_mode=v2168.AnimationMode.BLOCKS,
            animation_seconds=0.5,
            integrity_value=1.0,
            integrity_seed=9,
            pivot=v2168.Vec3(x=0.0, y=1.0, z=2.0),
        ),
        redstone_save_mode=v2168.StructureRedstoneSaveMode.SAVES_TO_DISK,
    ),
    trigger=True,
    is_waterlogged=False,
)

GOLDENS = [
    pytest.param(PACKET_1001, V1001, id="v1001"),
    pytest.param(PACKET_2168, V2168, id="v2168"),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_structure_block_update_is_packet_90(version):
    assert version.PACKETS[90] is version.StructureBlockUpdatePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_structure_block_update_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_structure_block_update_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_a_present_v2168_redacted_name_costs_its_own_string():
    packet = copy.copy(PACKET_2168)
    packet.data.structure_name.redacted_string = "redacted"
    assert len(bytes(packet)) == len(V2168) + 9


def test_a_present_v2168_redacted_name_round_trips():
    packet = copy.copy(PACKET_2168)
    packet.data.structure_name.redacted_string = "redacted"
    assert v2168.StructureBlockUpdatePacket.from_bytes(bytes(packet)) == packet


def test_a_v1001_body_decodes_as_a_v2168_one_and_is_wrong():
    wrong = copy.copy(PACKET_2168)
    wrong.data.redstone_save_mode = 2
    assert v2168.StructureBlockUpdatePacket.from_bytes(V1001) == wrong
